import numpy as np
from scipy.spatial.transform import Rotation as R
from scipy.optimize import least_squares
origins=[([0,0,.333],0),([0,0,0],-np.pi/2),([0,-.316,0],np.pi/2),([.0825,0,0],np.pi/2),([-.0825,.384,0],-np.pi/2),([0,0,0],np.pi/2),([.088,0,0],np.pi/2)]
limits=np.array([[-2.8973,2.8973],[-1.7628,1.7628],[-2.8973,2.8973],[-3.0718,-.0698],[-2.8973,2.8973],[-.0175,3.7525],[-2.8973,2.8973]])
def tf(p,rot):
 t=np.eye(4);t[:3,:3]=rot;t[:3,3]=p;return t
def fk(q):
 t=tf([0,-.4,.78],R.from_euler('z',np.pi/2).as_matrix())
 for a,(p,rx) in zip(q,origins):t=t@tf(p,R.from_euler('x',rx).as_matrix())@tf([0,0,0],R.from_euler('z',a).as_matrix())
 return t@tf([0,0,.107],R.from_euler('z',-np.pi/4).as_matrix())
def ik(p,rot,q0):
 def err(q):
  t=fk(q)
  return np.r_[10*(t[:3,3]-p),R.from_matrix(rot@t[:3,:3].T).as_rotvec(),.01*(q-q0)]
 res=least_squares(err,q0,bounds=(limits[:,0]+.001,limits[:,1]-.001),max_nfev=300,ftol=1e-10,xtol=1e-10,gtol=1e-10)
 if np.linalg.norm(fk(res.x)[:3,3]-p)>.005:raise ValueError(('IK position',res.fun,res.x))
 return res.x
if __name__=='__main__':
 import json
 s=json.load(open('/app/output/initial/meta.json'))['proprio']['now'];t=fk(s[:7]);print(t); print('actual',s[16:23]);print('quat',R.from_matrix(t[:3,:3]).as_quat()[[3,0,1,2]])
